<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';const p=defineProps<{ticket:any;categories:any[];staff:any[];statuses:string[];priorities:string[]}>();const reply=useForm({body:''}),note=useForm({body:''}),details=useForm({category_id:p.ticket.category_id,priority:p.ticket.priority,assigned_user_id:p.ticket.assigned_user_id,status:p.ticket.status,resolution_summary:p.ticket.resolution_summary??''});</script><template><Head :title="ticket.ticket_number"/><div class="space-y-6 p-6"><PageHeader :title="`${ticket.ticket_number} — ${ticket.subject}`" :description="`${ticket.customer} · ${ticket.customer_email}`"><template #actions><Button variant="outline" as-child><Link href="/admin/support/tickets">Back</Link></Button></template></PageHeader><div class="grid gap-6 xl:grid-cols-[1fr_360px]"><main class="space-y-5"><div class="rounded-lg border bg-card p-5 whitespace-pre-wrap">{{ticket.description}}</div><article v-for="m in ticket.messages" :key="m.id" class="rounded-lg border p-4" :class="m.type==='internal_note'?'border-amber-300 bg-amber-50/40 dark:bg-amber-950/20':''"><div class="flex justify-between"><strong>{{m.author_name}} <span v-if="m.type==='internal_note'">· Internal note</span></strong><span class="text-xs text-muted-foreground">{{m.created_at}}</span></div><p class="mt-3 whitespace-pre-wrap">{{m.body}}</p><ul v-if="m.attachments?.length" class="mt-3 space-y-2"><li v-for="a in m.attachments" :key="a.id" class="flex items-center justify-between gap-3 rounded-md border p-2 text-sm"><span>{{a.name}}</span><div v-if="!a.redacted_at" class="flex gap-2"><Button size="sm" variant="outline" as-child><a :href="`/admin/support/tickets/${ticket.uuid}/attachments/${a.id}`">Download</a></Button><form @submit.prevent="details.delete(`/admin/support/tickets/${ticket.uuid}/attachments/${a.id}`,{data:{reason:'Redacted by administrator.'},preserveScroll:true})"><Button size="sm" variant="destructive" type="submit">Redact</Button></form></div><span v-else class="text-muted-foreground">Redacted</span></li></ul></article><div class="grid gap-4 lg:grid-cols-2"><form class="rounded-lg border bg-card p-4" @submit.prevent="reply.post(`/admin/support/tickets/${ticket.uuid}/reply`,{onSuccess:()=>reply.reset()})"><h2 class="font-semibold">Reply to customer</h2><textarea v-model="reply.body" class="mt-3 min-h-36 w-full rounded-md border bg-background p-3" required/><Button class="mt-3">Send Reply</Button></form><form class="rounded-lg border border-amber-300 p-4" @submit.prevent="note.post(`/admin/support/tickets/${ticket.uuid}/notes`,{onSuccess:()=>note.reset()})"><h2 class="font-semibold">Internal note</h2><textarea v-model="note.body" class="mt-3 min-h-36 w-full rounded-md border bg-background p-3" required/><Button class="mt-3" variant="outline">Add Note</Button></form></div></main><aside><form class="space-y-4 rounded-lg border bg-card p-4" @submit.prevent="details.patch(`/admin/support/tickets/${ticket.uuid}`)"><h2 class="font-semibold">Ticket details</h2><label class="block text-sm">Status<select v-model="details.status" class="mt-1 h-10 w-full rounded-md border bg-background px-3"><option v-for="x in statuses" :value="x">{{x}}</option></select></label><label class="block text-sm">Priority<select v-model="details.priority" class="mt-1 h-10 w-full rounded-md border bg-background px-3"><option v-for="x in priorities" :value="x">{{x}}</option></select></label><label class="block text-sm">Category<select v-model="details.category_id" class="mt-1 h-10 w-full rounded-md border bg-background px-3"><option :value="null">Uncategorized</option><option v-for="x in categories" :value="x.id">{{x.name}}</option></select></label><label class="block text-sm">Assignee<select v-model="details.assigned_user_id" class="mt-1 h-10 w-full rounded-md border bg-background px-3"><option :value="null">Unassigned</option><option v-for="x in staff" :value="x.id">{{x.name}}</option></select></label><label class="block text-sm">Resolution summary<textarea v-model="details.resolution_summary" class="mt-1 min-h-24 w-full rounded-md border bg-background p-3"/></label><Button class="w-full">Save Changes</Button></form></aside></div></div></template>